import django.db.models.deletion
from django.db import migrations, models


def give_single_size(apps, schema_editor):
    """Lines of a product that now has exactly one size get that size, so checkout still works."""
    CartItem = apps.get_model("cart", "CartItem")
    ProductSize = apps.get_model("products", "ProductSize")
    for item in CartItem.objects.filter(size__isnull=True):
        sizes = list(ProductSize.objects.filter(product_id=item.product_id, is_active=True)[:2])
        if len(sizes) == 1:
            CartItem.objects.filter(pk=item.pk).update(size=sizes[0])


